matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.colors import TwoSlopeNorm
R=Path(__file__).resolve().parents[1];P=['Chen','Wallen','Zhou','Guo','Lacruz','Li']
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'pdf.fonttype':42,'ps.fonttype':42,'savefig.facecolor':'white'})
def load(p):
 with (R/p).open() as f:return list(csv.DictReader(f,delimiter='\t'))
def write(p,rows):
 with (R/p).open('w',newline='') as f:
  w=csv.DictWriter(f,rows[0].keys(),delimiter='\t',lineterminator='\n');w.writeheader();w.writerows(rows)
def num(x,dec=3):return 'NA' if x=='NA' else f'{float(x):.{dec}f}'
def pct(x):return 'NA' if x=='NA' else f'{100*float(x):.2f}%'
def md(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)+'\n'
def save(fig,name):
 fig.savefig(R/'08_figures'/f'{name}.png',dpi=300,bbox_inches='tight');fig.savefig(R/'08_figures'/f'{name}.pdf',bbox_inches='tight');plt.close(fig)
def heatmap(values,labels,title,cbarlabel,name,norm=None,cmap='viridis',note=''):
 fig,ax=plt.subplots(figsize=(10,8));cm=plt.get_cmap(cmap).copy();cm.set_bad('#f2f3f5');im=ax.imshow(np.ma.masked_invalid(values),cmap=cm,norm=norm,vmin=None if norm else 0,vmax=None if norm else 1)
 ax.set_xticks(range(6),P);ax.set_yticks(range(6),P);ax.xaxis.tick_top();ax.xaxis.set_label_position('top');ax.set_xlabel('Study B · edge absent',labelpad=13);ax.set_ylabel('Study A · edge source');ax.set_title(title,pad=68,fontweight='bold',fontsize=14)
 for i in range(6):
  for j in range(6):
   if i==j:
    ax.add_patch(plt.Rectangle((j-.5,i-.5),1,1,facecolor='white',edgecolor='white'));continue
   rgba=im.cmap(im.norm(values[i,j])) if np.isfinite(values[i,j]) else (1,1,1,1);luminance=sum(rgba[k]*[.2126,.7152,.0722][k] for k in range(3));ax.text(j,i,labels[i][j],ha='center',va='center',fontsize=10.5,color='black' if luminance>.53 else 'white')
 ax.set_xticks(np.arange(-.5,6,1),minor=True);ax.set_yticks(np.arange(-.5,6,1),minor=True);ax.grid(which='minor',color='white',linewidth=2);ax.tick_params(which='both',length=0);[s.set_visible(False) for s in ax.spines.values()];fig.colorbar(im,ax=ax,shrink=.78,pad=.035,label=cbarlabel);fig.text(.13,.055,note,fontsize=9,ha='left');fig.subplots_adjust(bottom=.12,top=.78);save(fig,name)
def main():
 primary=load('04_source_excluded_recovery/stage5A_directional_recovery_summary.tsv');strict=load('04_source_excluded_recovery/stage5A_strict_directional_recovery_summary.tsv');null=load('07_statistics/stage5A_null_summary.tsv');ind=load('qc/stage5A_independent_recalculation.tsv');assert all(x['status']=='PASS' for x in ind)
 audit=load('00_input_audit/stage5A_frozen_pairset_audit.tsv');uni=load('02_universe_audit/stage5A_universe_audit.tsv');sense=load('07_statistics/stage5A_lacruz_MHO_sensitivity.tsv');shared=load('07_statistics/stage5A_shared_pair_reference.tsv');sources=load('00_input_audit/stage5A_study_source_sets.tsv');lookup={(s['study_A'],s['study_B'],s['null_model']):s for s in null};joined=[]
 for s in primary:
  a=lookup[(s['study_A'],s['study_B'],'NullA')];b=lookup[(s['study_A'],s['study_B'],'NullB')]
  joined.append(dict(study_A=s['study_A'],study_B=s['study_B'],directional_pairs=s['directional_pairs'],recovered_after_AB_exclusion=s['AB_source_excluded_recovered'],recovery_rate=s['AB_source_excluded_recovery_rate'],baseline_recovered=s['baseline_recovered'],pairs_lost_after_AB_exclusion=s['pairs_lost_after_AB_exclusion'],nullA_enrichment=a['enrichment'],nullA_empirical_p=a['empirical_p'],nullA_BH_p=a['BH_adjusted_p'],nullB_enrichment=b['enrichment'],nullB_empirical_p=b['empirical_p'],nullB_BH_p=b['BH_adjusted_p'],nullA_status=a['status'],nullB_status=b['status']))
 write('07_statistics/stage5A_primary_delivery_table.tsv',joined)
 rec=np.full((6,6),np.nan);labels=[['']*6 for _ in P]
 for s in primary:
  i,j=P.index(s['study_A']),P.index(s['study_B']);n=int(s['directional_pairs']);rec[i,j]=float(s['AB_source_excluded_recovery_rate']) if n else np.nan;labels[i][j]=f"{s['AB_source_excluded_recovered']}/{n}\n{100*rec[i,j]:.1f}%" if n else '0/0\nNA'
 heatmap(rec,labels,'Independent recovery of directional complementarity pairs','Recovery after combined A+B source exclusion','Stage5A_directional_complementarity_recovery_heatmap',note='Cell: recovered / directional pairs and recovery rate. Recovery requires ≥2 non-source BioProjects.\nPrimary universe: published-network nodes of B. Guo → Li has no eligible pairs.')
 for model,name in [('NullA','Stage5A_directional_null_enrichment_heatmap'),('NullB','Stage5A_directional_nullB_enrichment_heatmap')]:
  val=np.full((6,6),np.nan);lab=[['']*6 for _ in P]
  for s in null:
   if s['null_model']!=model:continue
   i,j=P.index(s['study_A']),P.index(s['study_B'])
   if s['enrichment']=='NA':lab[i][j]='NA\n(empty set)' if s['status']=='NA_EMPTY_DIRECTIONAL_SET' else 'NA\n(no legal swap)' if s['status']=='NA_NO_LEGAL_SWAP' else 'NA\n(swap cap)' if s['status']=='NA_SWAP_CAP' else 'NA';continue
   val[i,j]=float(s['enrichment']);lab[i][j]=f"{val[i,j]:.2f}×"+('\n*' if float(s['BH_adjusted_p'])<.05 else '')
  norm=TwoSlopeNorm(vmin=min(.90 if model=='NullB' else .5,float(np.nanmin(val))),vcenter=1.,vmax=max(1.10 if model=='NullB' else 1.5,float(np.nanmax(val))))
  note='* BH-adjusted P < 0.05; BH family includes all valid directions for this null.\n'+('Null A: B-node-universe constrained random-pair null; 1,000 replicates.' if model=='NullA' else 'Null B: preserve D graph degrees and nodes; exclude B edges; 50E successful swaps, 1,000 restarts.')
  heatmap(val,lab,f'{model.replace("Null","Null ")} · observed / random recovery','Recovery enrichment',name,norm=norm,cmap='BrBG',note=note)
 fig,ax=plt.subplots(figsize=(8.5,7));palette=plt.get_cmap('tab10');markers=['o','s','^','D','P','X']
 for i,A in enumerate(P):
  rs=[s for s in primary if s['study_A']==A and s['baseline_recovery_rate']!='NA'];ax.scatter([float(s['baseline_recovery_rate']) for s in rs],[float(s['AB_source_excluded_recovery_rate']) for s in rs],label=A,s=70,marker=markers[i],color=palette(i),edgecolor='white',linewidth=.7,zorder=3,alpha=.85)
 ax.plot([0,1],[0,1],'--',color='#707070',linewidth=1.3,label='y = x',zorder=1);ax.set(xlim=(0,1.035),ylim=(0,1.035),xlabel='Baseline MACK-DB recovery rate',ylabel='Recovery after combined A+B source exclusion',title='Effect of excluding both studies’ source BioProjects');ax.set_aspect('equal');ax.grid(alpha=.15);ax.text(.04,.94,'29 non-empty directions: no pair-level recovery loss\nGuo → Li: 0 pairs, recovery rate NA',transform=ax.transAxes,va='top',fontsize=10);ax.legend(title='Edge source A',loc='lower right',frameon=False,ncol=2);ax.annotate('Li → Zhou',(.527397,.527397),xytext=(.29,.59),arrowprops=dict(arrowstyle='-',color='grey'),fontsize=10);fig.text(.14,.025,'Overlapping points reflect equal recovery rates; all 29 valid directions are plotted without jitter.',fontsize=9);fig.tight_layout(rect=(0,.05,1,1));save(fig,'Stage5A_source_exclusion_effect')
 totals={k:sum(int(x[k]) for x in primary) for k in ['directional_pairs','baseline_recovered','AB_source_excluded_recovered','pairs_lost_after_AB_exclusion','total_project_support_entries_removed','pairs_with_any_source_support_removed']};valid=[s for s in primary if s['AB_source_excluded_recovery_rate']!='NA'];rates=np.array([float(s['AB_source_excluded_recovery_rate']) for s in valid]);a=[s for s in null if s['null_model']=='NullA' and s['status']=='VALID'];b=[s for s in null if s['null_model']=='NullB' and s['status']=='VALID'];asig=sum(float(s['BH_adjusted_p'])<.05 for s in a);bsig=sum(float(s['BH_adjusted_p'])<.05 for s in b);aboveA=sum(float(s['observed_recovery_rate'])>float(s['null_mean_recovery']) for s in a);aboveB=sum(float(s['observed_recovery_rate'])>float(s['null_mean_recovery']) for s in b);diff=[100*float(s['recovery_rate_difference']) for s in sense];sr=np.array([float(s['AB_source_excluded_recovery_rate']) for s in shared]);highest=[s['study_A']+'→'+s['study_B']+f" ({s['AB_source_excluded_recovered']}/{s['directional_pairs']})" for s in valid if float(s['AB_source_excluded_recovery_rate'])==rates.max()];lowest=sorted(valid,key=lambda s:float(s['AB_source_excluded_recovery_rate']))[:3]
 stats=dict(primary_comparisons=30,strict_tested_universe_comparisons=len(strict),nonempty_primary_comparisons=len(valid),nullA_valid=len(a),nullA_above_mean=aboveA,nullA_BH_significant=asig,nullB_feasible=len(b),nullB_above_mean=aboveB,nullB_BH_significant=bsig,primary_directional_pair_occurrences=totals['directional_pairs'],source_excluded_recovered_occurrences=totals['AB_source_excluded_recovered'],source_exclusion_pair_losses=totals['pairs_lost_after_AB_exclusion'],source_support_entries_removed=totals['total_project_support_entries_removed'],median_recovery_rate=float(np.median(rates)),min_recovery_rate=float(rates.min()),max_recovery_rate=float(rates.max()),MHO_change_percentage_points_min=min(diff),MHO_change_percentage_points_max=max(diff),shared_reference_median=float(np.median(sr)))
 (R/'07_statistics/stage5A_delivery_counts.json').write_text(json.dumps(stats,indent=2)+'\n')
 headers=['A','B','Directional pairs','Recovered after A+B exclusion','Recovery rate','Null A enrichment','Null A P','Null A BH P','Null B enrichment','Null B P','Null B BH P']
 table=md(headers,[[s['study_A'],s['study_B'],s['directional_pairs'],s['recovered_after_AB_exclusion'],pct(s['recovery_rate']),num(s['nullA_enrichment']),num(s['nullA_empirical_p']),num(s['nullA_BH_p']),num(s['nullB_enrichment']),num(s['nullB_empirical_p']),num(s['nullB_BH_p'])] for s in joined])
 result=f"""We evaluated directional cross-study complementarity across 30 ordered comparisons of six published human-gut studies using frozen GTDB R226 association sets. Within the published-network node universe of each comparison study B, eligible pairs were reported by study A, and both taxa were represented as nodes in study B's published network, but the edge was not reported. Twenty-nine comparisons contained eligible pairs; Guo→Li contained none. Following combined source exclusion of all overlapping BioProjects from both studies, recovery supported by at least two other BioProjects ranged from {100*rates.min():.1f}% to {100*rates.max():.1f}% (median, {100*np.median(rates):.1f}%). Independent BioProject support persisted for {totals['AB_source_excluded_recovered']:,} of {totals['directional_pairs']:,} directional pair occurrences, which can recur across comparisons. Removal of {totals['total_project_support_entries_removed']:,} direction-specific project-support entries eliminated no recovered pairs. Recovery exceeded the Null A mean in {aboveA} comparisons, with {asig} significant after Benjamini–Hochberg correction. The degree-preserving Null B was feasible for {len(b)} comparisons, of which {bsig} were significant. Including exploratory Lacruz MHO networks changed recovery rates by {min(diff):.2f} to {max(diff):+.2f} percentage points. Shared published associations had a median independent recovery of {100*np.median(sr):.1f}%. These findings support complementary, recurrent association evidence across independent BioProjects; published edge absence alone does not establish a negative association test or a causal biological relationship."""
 method="""We reused six frozen publication-level GTDB R226 undirected association sets without taxonomic remapping. For each ordered A→B comparison, directional pairs were defined as edges in A but absent from B, restricted to endpoints in B's published-network node universe. Additional analyses used existing mapped identities from directly evidenced complete inference-taxon sets. Primary Lacruz sets excluded exploratory MHO networks; sensitivity analyses changed only Lacruz membership. We applied combined source exclusion using the union of both studies' overlapping BioProjects and synchronously removed project IDs, correlations, P values, and sample counts. Recovery required independent BioProject support from at least two remaining projects. Audited absence from the frozen f≥2 database implied non-recovery, while unobserved subthreshold support counts remained unknown. Null A sampled the observed edge count without replacement from all possible B-node pairs excluding B edges. Null B independently restarted the observed graph for each replicate and performed 50E successful double-edge swaps, preserving nodes, degrees, and edge count while rejecting loops, duplicates, and B edges. Both nulls used 1,000 replicates and identical source-excluded database lookups. Null B attempts were capped at max(10,000, 100×50E); infeasible comparisons remained NA. Empirical P values used (1+exceedances)/1001, with minimum reported P=0.001. Benjamini–Hochberg correction used unrounded P values separately across valid directions for each null. Independent scripts verified pair-level support removal, recovery, randomized graphs, and statistics."""
 for name,text in [('MANUSCRIPT_RESULT_DRAFT',result),('MANUSCRIPT_METHOD_DRAFT',method)]:
  assert 150<=len(text.split())<=250,(name,len(text.split()));(R/'reports'/f'{name}.md').write_text(text+'\n')
 parts=['# Stage 5A — Directional cross-study complementarity and independent MACK-DB recovery','Status: **Stage 5A COMPLETE**. All new results are confined to this directory. No FastSpar rerun, frozen-set modification, or new GTDB assignment was performed.','## Scope and primary interpretation',"The primary endpoint is **A-positive / B-node-visible / B-edge-absent**. Specifically, **both taxa were represented as nodes in study B's published network, but the edge was not reported**. The endpoint does not assert that B tested the pair and obtained a negative result. All 30 ordered comparisons are retained, including the empty Guo→Li set. Primary and strict summaries are separate files; primary nulls and BH families use only the node-visible analysis.",'## Frozen study sets',md(['Study','Paper pairs','Network nodes','SHA-256 verified'],[[s['study'],s['pair_count'],s['unique_taxa'],s['status']] for s in audit]),'Stage 4A pair hashes and all pair intersections match frozen outputs. Lacruz primary excludes MHO; the sensitivity set is used only in ten Lacruz-involved directions.','## Complete inference-taxon identity evidence and strict analyses',md(['Study','Complete raw identity evidence','Raw taxa','Mapped unique GTDB taxa','Unresolved raw taxa','Primary nodes'],[[s['study'],s['strict_available'],s['strict_raw_tested_taxa'],s['strict_mapped_unique_GTDB_taxa'],s['strict_unresolved_raw_taxa'],s['published_network_nodes']] for s in uni]),'There are 15 additional strict comparisons (B=Wallen, Guo, or Li). The entire raw input identity set is evidenced, but the strict GTDB universe is its existing, unambiguously mapped portion. These results use **A-positive / B-testable / B-edge-absent** and are separate from the primary analysis. Frozen decisions were reused by exact taxon identity/format normalization; no taxonomic inference, genome search, or reassignment was performed. For Wallen, the paper-level union is used; taxon membership does not prove every possible pair was evaluated in one particular subnetwork. Guo has 100 raw taxa mapping to 91 unique GTDB taxa, so its strict and primary node universes coincide.', '\n\n'.join('**'+s['study']+'**: '+s['evidence']+' '+s['limitation']+' Evidence files: '+s['evidence_files'] for s in uni),md(['A','B','Strict pairs','Recovered','Recovery rate'],[[s['study_A'],s['study_B'],s['directional_pairs'],s['AB_source_excluded_recovered'],pct(s['AB_source_excluded_recovery_rate'])] for s in strict]),'## Source exclusion and support accounting',md(['Study','Overlapping source BioProjects'],[[s['study'],s['actual_overlapping_sources']] for s in sources]),'Source projects derive from the frozen Stage 4B network-source configuration, unioned at paper level and intersected with the actual database support universe. Every direction removes source(A) ∪ source(B), including B projects even when B did not report that edge. Aliases use the existing Stage 3B canonical accession decisions. Four semicolon-delimited project vectors are filtered by the same indices: ID, correlation, P value, and sample count.',f"The original f≥2 database was completely scanned: 653,071 unique associations and 859 supporting BioProjects. Original baseline vectors reconcile with Stage 4B. Pairs absent from this audited database cannot become recovered after deleting supports, but their exact sub-f2 support count is **NA, not an imputed zero**. Median and IQR support statistics therefore cover known counts only, with known/unknown denominators included in each summary. Across primary directional occurrences, {totals['total_project_support_entries_removed']:,} support entries were removed from {totals['pairs_with_any_source_support_removed']:,} pair occurrences. Source exclusion eliminated **{totals['pairs_lost_after_AB_exclusion']}** recovered pairs: all baseline-recovered pairs retained at least two non-source BioProjects. The independent script directly rechecked every reported pair against a fresh original-database scan.",'## Thirty primary directional comparisons',table,'P values are displayed to three decimals; the minimum empirical P is reported as 0.001. Exact (1+exceedances)/1001 values are retained in raw_empirical_p and empirical_p_exact. BH correction uses these unrounded values. The comprehensive primary recovery TSV also gives the median/IQR of known remaining support and source-exclusion losses.',f"Counts across directions total {totals['directional_pairs']:,} pair occurrences and {totals['AB_source_excluded_recovered']:,} recovered occurrences; these are not disjoint associations or independent repeated observations. The median nonempty-direction recovery is {100*np.median(rates):.2f}%. Highest: {', '.join(highest)}. Lowest: "+'; '.join(s['study_A']+'→'+s['study_B']+' '+pct(s['AB_source_excluded_recovery_rate'])+f" ({s['AB_source_excluded_recovered']}/{s['directional_pairs']})" for s in lowest)+'. The 100% rates for small sets should be read with their denominators.',md(['A','B','Baseline recovered','After A+B exclusion','Pairs lost','Support entries removed'],[[s['study_A'],s['study_B'],s['baseline_recovered'],s['AB_source_excluded_recovered'],s['pairs_lost_after_AB_exclusion'],s['total_project_support_entries_removed']] for s in primary]),'## Null models and multiplicity',f"Null A: {len(a)}/30 valid comparisons; {aboveA} observed rates exceed the null mean; **{asig}/30 BH-significant**. Each of 1,000 replicates samples exactly E unique pairs without replacement from all_pairs(B network nodes) minus E_B, using the same A+B-excluded lookup as the observed comparison. The B universe, rather than only the smaller directional graph's node set, defines this random-pair expectation.",f"Null B: **{len(b)}/30 feasible**; {aboveB} observed rates exceed its mean; **{bsig} BH-significant**. Each replicate restarts the original D graph, targets exactly 50E successful swaps, and permits at most max(10,000,100×50E) proposals. Every stored randomized graph passes exact degree, node-set, edge-count, simple-graph and forbidden-B-edge checks. The two orientations of a selected edge pair are proposed with equal probability; failed proposals do not count as successful swaps. This is a finite degree-constrained rewiring ensemble; convergence to a uniform distribution over all possible constrained graphs is not claimed. No infeasible Null B was replaced by Null A.",md(['A','B','Null B status','Reason'],[[s['study_A'],s['study_B'],s['status'],s['reason']] for s in null if s['null_model']=='NullB' and s['status']!='VALID']),md(['A','B','Null','Reason for NA z-score/enrichment'],[[s['study_A'],s['study_B'],s['null_model'],s['reason']] for s in null if s['status']=='VALID' and (s['z_score']=='NA' or s['enrichment']=='NA')]),'Degree preservation substantially narrows the set of BH-significant directions; widespread Null A enrichment should be interpreted at the random-pair null level. BH correction is applied separately to all valid primary directions for each null, never to a selected subset of P values. Empty observed sets have NA rates and do not enter a BH family. Null SD uses ddof=1. A zero-variance valid null retains its empirical P but has z=NA; null-mean zero would yield enrichment=NA. Seeds, candidate pairs, sampled indices, graph archives, swap attempts, and per-replicate results are retained. Strict, sensitivity and shared-reference analyses are descriptive and do not borrow primary null P values.','## Lacruz MHO sensitivity',md(['A','B','Primary E','MHO E','Primary recovered','MHO recovered','Primary rate','MHO rate','Change (pp)'],[[s['study_A'],s['study_B'],s['primary_directional_pair_count'],s['sensitivity_directional_pair_count'],s['primary_recovered'],s['sensitivity_recovered'],pct(s['primary_recovery']),pct(s['sensitivity_recovery']),f"{100*float(s['recovery_rate_difference']):+.2f}"] for s in sense]),f"Changes range from {min(diff):+.2f} to {max(diff):+.2f} percentage points. Independent descriptive recovery remains high in these ten comparisons, supporting that the primary complementarity description does not depend on including exploratory MHO. This sensitivity does not establish stability of null significance because nulls are specified for the primary set only. The actual overlapping source-project union is unchanged by MHO.",'## Shared published-association reference',md(['A','B','Shared E','Recovered','Recovery rate'],[[s['study_A'],s['study_B'],s['directional_pairs'],s['AB_source_excluded_recovered'],pct(s['AB_source_excluded_recovery_rate'])] for s in shared]),f"The 15 unordered shared-pair references have recovery rates of {100*sr.min():.2f}%–{100*sr.max():.2f}% (median {100*np.median(sr):.2f}%), compared with a {100*np.median(rates):.2f}% median across nonempty directional comparisons. These differently sized, overlapping sets provide descriptive context. The optional Fisher comparison was not performed; no causal or independent-observation interpretation is attached to this contrast.",'## Figures','- [Recovery heatmap](08_figures/Stage5A_directional_complementarity_recovery_heatmap.png) / [PDF](08_figures/Stage5A_directional_complementarity_recovery_heatmap.pdf)\n- [Null A enrichment](08_figures/Stage5A_directional_null_enrichment_heatmap.png) / [PDF](08_figures/Stage5A_directional_null_enrichment_heatmap.pdf)\n- [Null B enrichment](08_figures/Stage5A_directional_nullB_enrichment_heatmap.png) / [PDF](08_figures/Stage5A_directional_nullB_enrichment_heatmap.pdf)\n- [Source exclusion effect](08_figures/Stage5A_source_exclusion_effect.png) / [PDF](08_figures/Stage5A_source_exclusion_effect.pdf)','The source-exclusion scatter includes all 29 defined primary rates on y=x. Guo→Li is explicitly recorded as undefined, and equal-coordinate points overlap without jitter.','## Independent verification and reproducibility',f"The independent script passed {len(ind)} checks. It imports neither analysis generator, independently rescans the original DB, recalculates pair sets/recovery/losses, validates stored Null A samples and all Null B graphs, recalculates empirical P values and BH, and verifies before/after hashes for all registered frozen inputs. Seeded random original-support spotchecks cover Chen→Wallen, Wallen→Chen, Zhou→Guo, Guo→Zhou, Lacruz→Li and Li→Lacruz. Key evidence is in [independent recalculation](qc/stage5A_independent_recalculation.tsv), [spotchecks](qc/stage5A_original_DB_random_spotchecks.tsv), [QC](qc/stage5A_qc_summary.tsv), and [input integrity](qc/stage5A_frozen_input_integrity.tsv).",'Scripts: `logs/build_stage5a.py` → `logs/run_nulls.py` → `logs/finalize_statistics.py` → `logs/independent_audit.py` → `logs/render_delivery.py`. Interpreter: `/home/wangmengyang/anaconda3/bin/python -s -B`; set MPLCONFIGDIR inside `logs/`. Rerunning is unnecessary for this completed delivery. Protocol: [stage5A_null_protocol.json](00_input_audit/stage5A_null_protocol.json). Base seed: 20261009, with independent deterministic direction/model/replicate seeds.','## Manuscript-safe interpretation','MACK-DB provides independent BioProject-level support for associations reported by one external study but absent as edges from another published network. It complements individual published networks by integrating recurrent evidence across independent BioProjects. The evidence concerns recurrent associations, not a gold-standard judgment of either publication, direct microbial interactions, or causal effects. Independence here is defined by non-source BioProject identifiers; it is not an additional proof of participant-level independence across every database project.','## MANUSCRIPT_RESULT_DRAFT',result,'## MANUSCRIPT_METHOD_DRAFT',method]
 (R/'STAGE5A_REPORT.md').write_text('\n\n'.join(parts)+'\n')
 (R/'reports/stage5A_final_console_summary.md').write_text('Stage 5A COMPLETE\n\n'+table+'\n'+json.dumps(stats,indent=2)+'\n')
 (R/'reports/stage5A_figure_captions.md').write_text('Figure 1. Directional A-positive / B-node-visible / B-edge-absent pairs independently recovered after removing both studies’ source projects. Each cell shows recovered / eligible pairs and percent recovery. Diagonal blank; empty Guo→Li set is NA.\n\nFigure 2. Recovery enrichment over the B-node-universe constrained Null A. An asterisk denotes BH-adjusted P < 0.05 across all valid primary directions. All replicates use combined source exclusion.\n\nFigure 3 (additional). Recovery enrichment over the constrained degree-preserving Null B, with exact observed node/degree sets and no published B edges. NA indicates an empty observed set, no legal swap, or failure to reach the swap target within the documented attempt cap.\n\nFigure 4. Baseline and combined-source-excluded recovery rates. All 29 nonempty directions lie on y=x; support removal did not reduce any primary pair below two projects. Coincident values overlap without jitter.\n')
 print(json.dumps(stats,indent=2));print('MANUSCRIPT_WORD_COUNTS',len(result.split()),len(method.split()));print('REPORT_AND_FIGURES_GENERATED')
